  1→import { useEffect, useState } from "react";
  2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher } from "react-router";
  4→import { useAppBridge } from "@shopify/app-bridge-react";
  5→import { authenticate } from "../shopify.server";
  6→import db from "../db.server";
  7→import { getPlan, hasFeature } from "../lib/plans";
  8→
  9→// ---------------------------------------------------------------------------
 10→// Types
 11→// ---------------------------------------------------------------------------
 12→
 13→interface GeneralSettings {
 14→  unitSystem: string;
 15→  defaultCategory: string;
 16→  autoPublish: boolean;
 17→}
 18→
 19→// ---------------------------------------------------------------------------
 20→// Loader
 21→// ---------------------------------------------------------------------------
 22→
 23→export const loader = async ({ request }: LoaderFunctionArgs) => {
 24→  const { session } = await authenticate.admin(request);
 25→  const shop = session.shop;
 26→
 27→  const [
 28→    chartCount,
 29→    assignmentCount,
 30→    widgetConfig,
 31→    recommenderConfig,
 32→    subscription,
 33→  ] = await Promise.all([
 34→    db.sizeChart.count({ where: { shop } }),
 35→    db.chartAssignment.count({ where: { shop } }),
 36→    db.widgetConfig.findUnique({ where: { shop } }),
 37→    db.recommenderConfig.findUnique({ where: { shop } }),
 38→    db.subscription.findUnique({ where: { shop } }),
 39→  ]);
 40→
 41→  const plan = getPlan(subscription?.planId ?? "free");
 42→
 43→  return {
 44→    shop,
 45→    chartCount,
 46→    assignmentCount,
 47→    hasWidgetConfig: widgetConfig !== null,
 48→    widgetDisplayMode: widgetConfig?.displayMode ?? null,
 49→    hasRecommenderConfig: recommenderConfig !== null,
 50→    recommenderEnabled: recommenderConfig?.enabled ?? false,
 51→    plan,
 52→    isPriority: hasFeature(plan.id, "prioritySupport"),
 53→    isFreePlan: plan.id === "free",
 54→  };
 55→};
 56→
 57→// ---------------------------------------------------------------------------
 58→// Action
 59→// ---------------------------------------------------------------------------
 60→
 61→export const action = async ({ request }: ActionFunctionArgs) => {
 62→  const { session } = await authenticate.admin(request);
 63→  const shop = session.shop;
 64→  const formData = await request.formData();
 65→  const intent = formData.get("intent") as string;
 66→
 67→  try {
 68→    switch (intent) {
 69→      case "export-data": {
 70→        const charts = await db.sizeChart.findMany({
 71→          where: { shop },
 72→          include: { assignments: true },
 73→        });
 74→        const payload = {
 75→          exportedAt: new Date().toISOString(),
 76→          shop,
 77→          charts: charts.map((c) => ({
 78→            id: c.id,
 79→            name: c.name,
 80→            type: c.type,
 81→            category: c.category,
 82→            data: c.data,
 83→            isDefault: c.isDefault,
 84→            status: c.status,
 85→            createdAt: c.createdAt.toISOString(),
 86→            assignments: c.assignments.map((a) => ({
 87→              assignmentType: a.assignmentType,
 88→              assignmentValue: a.assignmentValue,
 89→            })),
 90→          })),
 91→        };
 92→        return {
 93→          ok: true,
 94→          intent: "export-data",
 95→          message: `${charts.length} chart${charts.length === 1 ? "" : "s"} exported`,
 96→          exportData: JSON.stringify(payload, null, 2),
 97→        };
 98→      }
 99→
100→      case "import-data": {
101→        const jsonRaw = formData.get("importJson") as string;
102→        if (!jsonRaw?.trim()) {
103→          return { error: "No JSON data provided", intent: "import-data" };
104→        }
105→        let parsed: { charts?: Array<{
106→          name: string;
107→          type?: string;
108→          category?: string;
109→          data?: string;
110→          isDefault?: boolean;
111→          status?: string;
112→          assignments?: Array<{ assignmentType: string; assignmentValue: string }>;
113→        }> };
114→        try {
115→          parsed = JSON.parse(jsonRaw) as typeof parsed;
116→        } catch {
117→          return { error: "Invalid JSON format", intent: "import-data" };
118→        }
119→        if (!Array.isArray(parsed.charts)) {
120→          return { error: "JSON must contain a 'charts' array", intent: "import-data" };
121→        }
122→        let imported = 0;
123→        for (const chart of parsed.charts) {
124→          if (!chart.name) continue;
125→          const existing = await db.sizeChart.findFirst({
126→            where: { shop, name: chart.name },
127→          });
128→          if (existing) continue;
129→          await db.sizeChart.create({
130→            data: {
131→              shop,
132→              name: chart.name,
133→              type: chart.type ?? "table",
134→              category: chart.category ?? "general",
135→              data: chart.data ?? "{}",
136→              isDefault: chart.isDefault ?? false,
137→              status: chart.status ?? "draft",
138→              assignments: chart.assignments
139→                ? {
140→                    create: chart.assignments.map((a) => ({
141→                      shop,
142→                      assignmentType: a.assignmentType,
143→                      assignmentValue: a.assignmentValue,
144→                    })),
145→                  }
146→                : undefined,
147→            },
148→          });
149→          imported++;
150→        }
151→        return {
152→          ok: true,
153→          intent: "import-data",
154→          message: `${imported} chart${imported === 1 ? "" : "s"} imported successfully`,
155→        };
156→      }
157→
158→      case "reset-widget": {
159→        await db.widgetConfig.deleteMany({ where: { shop } });
160→        return { ok: true, intent: "reset-widget", message: "Widget settings reset to defaults" };
161→      }
162→
163→      case "reset-analytics": {
164→        const deleted = await db.analyticsEvent.deleteMany({ where: { shop } });
165→        return {
166→          ok: true,
167→          intent: "reset-analytics",
168→          message: `${deleted.count} analytics event${deleted.count === 1 ? "" : "s"} cleared`,
169→        };
170→      }
171→
172→      case "delete-all-charts": {
173→        const confirm = formData.get("confirmText") as string;
174→        if (confirm !== "DELETE") {
175→          return { error: "Type DELETE to confirm", intent: "delete-all-charts" };
176→        }
177→        const deleted = await db.sizeChart.deleteMany({ where: { shop } });
178→        return {
179→          ok: true,
180→          intent: "delete-all-charts",
181→          message: `${deleted.count} chart${deleted.count === 1 ? "" : "s"} deleted`,
182→        };
183→      }
184→
185→      default:
186→        return { error: "Unknown action", intent };
187→    }
188→  } catch (error) {
189→    const message = error instanceof Error ? error.message : "An unexpected error occurred";
190→    return { error: message, intent };
191→  }
192→};
