194→// ---------------------------------------------------------------------------
195→// Sub-components
196→// ---------------------------------------------------------------------------
197→
198→function StatCard({
199→  label,
200→  value,
201→  sub,
202→}: {
203→  label: string;
204→  value: string | number;
205→  sub?: string;
206→}) {
207→  return (
208→    <s-box padding="base" borderWidth="base" borderRadius="base">
209→      <s-stack direction="block" gap="small-200">
210→        <s-heading>{String(value)}</s-heading>
211→        <s-text color="subdued">{label}</s-text>
212→        {sub && <s-text color="subdued">{sub}</s-text>}
213→      </s-stack>
214→    </s-box>
215→  );
216→}
217→
218→function StatusRow({
219→  label,
220→  configured,
221→  configuredLabel,
222→  notConfiguredLabel,
223→}: {
224→  label: string;
225→  configured: boolean;
226→  configuredLabel: string;
227→  notConfiguredLabel: string;
228→}) {
229→  return (
230→    <s-stack direction="inline" gap="base">
231→      <s-text>{label}</s-text>
232→      <s-badge tone={configured ? "success" : "neutral"}>
233→        {configured ? configuredLabel : notConfiguredLabel}
234→      </s-badge>
235→    </s-stack>
236→  );
237→}
238→
239→// ---------------------------------------------------------------------------
240→// Main Component
241→// ---------------------------------------------------------------------------
242→
243→export default function Settings() {
244→  const {
245→    shop,
246→    chartCount,
247→    assignmentCount,
248→    hasWidgetConfig,
249→    widgetDisplayMode,
250→    hasRecommenderConfig,
251→    recommenderEnabled,
252→    plan,
253→    isPriority,
254→    isFreePlan,
255→  } = useLoaderData<typeof loader>();
256→
257→  const fetcher = useFetcher<typeof action>();
258→  const shopify = useAppBridge();
259→  const isLoading = fetcher.state !== "idle";
260→
261→  // General settings (client-only — persisted in localStorage for now)
262→  const [unitSystem, setUnitSystem] = useState<string>("cm");
263→  const [defaultCategory, setDefaultCategory] = useState<string>("general");
264→  const [autoPublish, setAutoPublish] = useState<boolean>(false);
265→
266→  // Import text area
267→  const [importJson, setImportJson] = useState<string>("");
268→
269→  // Danger zone confirm text
270→  const [deleteConfirm, setDeleteConfirm] = useState<string>("");
271→
272→  // Export download trigger
273→  const [exportedJson, setExportedJson] = useState<string | null>(null);
274→
275→  useEffect(() => {
276→    if (!fetcher.data) return;
277→
278→    if ("ok" in fetcher.data) {
279→      shopify.toast.show(fetcher.data.message ?? "Done");
280→
281→      if (fetcher.data.intent === "export-data" && "exportData" in fetcher.data) {
282→        setExportedJson(fetcher.data.exportData as string);
283→      }
284→
285→      if (fetcher.data.intent === "import-data") {
286→        setImportJson("");
287→      }
288→
289→      if (fetcher.data.intent === "delete-all-charts") {
290→        setDeleteConfirm("");
291→      }
292→    } else if ("error" in fetcher.data) {
293→      shopify.toast.show(fetcher.data.error ?? "An error occurred", { isError: true });
294→    }
295→  }, [fetcher.data, shopify]);
296→
297→  // Trigger browser download when export data is ready
298→  useEffect(() => {
299→    if (!exportedJson) return;
300→    const blob = new Blob([exportedJson], { type: "application/json" });
301→    const url = URL.createObjectURL(blob);
302→    const a = document.createElement("a");
303→    a.href = url;
304→    a.download = `size-charts-${shop}-${new Date().toISOString().slice(0, 10)}.json`;
305→    a.click();
306→    URL.revokeObjectURL(url);
307→    setExportedJson(null);
308→  }, [exportedJson, shop]);
309→
310→  const submitIntent = (intent: string, extra?: Record<string, string>) => {
311→    const fd = new FormData();
312→    fd.set("intent", intent);
313→    if (extra) {
314→      for (const [k, v] of Object.entries(extra)) fd.set(k, v);
315→    }
316→    fetcher.submit(fd, { method: "post" });
317→  };
318→
319→  const CATEGORIES = [
320→    "general",
321→    "tops",
322→    "bottoms",
323→    "dresses",
324→    "shoes",
325→    "kids",
326→    "rings",
327→    "sportswear",
328→    "outerwear",
329→  ];
330→
331→  return (
332→    <s-page heading="Settings">
333→      {/* Primary action slot */}
334→      <s-button slot="primary-action" variant="primary" href="/app/pricing">
335→        {isFreePlan ? "Upgrade plan" : "Manage billing"}
336→      </s-button>
337→
338→      {/* ================================================================ */}
339→      {/* SECTION 1 — Account Overview                                      */}
340→      {/* ================================================================ */}
341→      <s-section heading="Account Overview">
342→        <s-stack direction="block" gap="base">
343→          <s-box padding="base" borderWidth="base" borderRadius="base">
344→            <s-stack direction="block" gap="small-200">
345→              <s-stack direction="inline" gap="small-200">
346→                <s-text>Store</s-text>
347→                <s-text color="subdued">{shop}</s-text>
348→              </s-stack>
349→              <s-divider />
350→              <s-stack direction="inline" gap="small-200">
351→                <s-text>Current plan</s-text>
352→                <s-badge tone={isFreePlan ? "neutral" : "success"}>{plan.name}</s-badge>
353→                <s-text color="subdued">
354→                  {plan.price === 0 ? "Free forever" : `$${plan.price}/mo`}
355→                </s-text>
356→              </s-stack>
357→              {isFreePlan && (
358→                <s-banner tone="info" heading="Upgrade for more features">
359→                  <s-stack direction="block" gap="small-200">
360→                    <s-text color="subdued">
361→                      Get unlimited charts, auto-assignment, CSV import/export, AI recommender, and analytics.
362→                    </s-text>
363→                    <s-button href="/app/pricing" variant="primary">View upgrade options</s-button>
364→                  </s-stack>
365→                </s-banner>
366→              )}
367→            </s-stack>
368→          </s-box>
369→
370→          <s-stack direction="inline" gap="base">
371→            <StatCard label="Size charts" value={chartCount} sub={`${plan.limits.maxCharts === -1 ? "Unlimited" : `${chartCount} of ${plan.limits.maxCharts}`} charts`} />
372→            <StatCard label="Assignments" value={assignmentCount} sub="Products, collections, tags" />
373→          </s-stack>
374→        </s-stack>
375→      </s-section>
376→
377→      {/* ================================================================ */}
378→      {/* SECTION 2 — General Settings                                      */}
379→      {/* ================================================================ */}
380→      <s-section heading="General Settings">
381→        <s-box padding="base" borderWidth="base" borderRadius="base">
382→          <s-stack direction="block" gap="base">
383→
384→            <s-stack direction="block" gap="small-200">
385→              <s-text>Default unit system</s-text>
386→              <s-text color="subdued">
387→                Sets the default measurement unit for new size charts. Customers can always switch.
388→              </s-text>
389→              <s-select
390→                label=""
391→                value={unitSystem}
392→                onChange={(e: Event) => setUnitSystem((e.target as HTMLSelectElement).value)}
393→              >
394→                <s-option value="cm">Centimeters (cm)</s-option>
395→                <s-option value="in">Inches (in)</s-option>
396→              </s-select>
397→            </s-stack>
398→
399→            <s-divider />
400→
401→            <s-stack direction="block" gap="small-200">
402→              <s-text>Default chart category</s-text>
403→              <s-text color="subdued">
404→                Pre-selected category when creating a new size chart from scratch.
405→              </s-text>
406→              <s-select
407→                label=""
408→                value={defaultCategory}
409→                onChange={(e: Event) => setDefaultCategory((e.target as HTMLSelectElement).value)}
410→              >
411→                {CATEGORIES.map((cat) => (
412→                  <s-option key={cat} value={cat}>
413→                    {cat.charAt(0).toUpperCase() + cat.slice(1)}
414→                  </s-option>
415→                ))}
416→              </s-select>
417→            </s-stack>
418→
419→            <s-divider />
420→
421→            <s-stack direction="inline" gap="base">
422→              <s-stack direction="block" gap="small-200">
423→                <s-text>Auto-publish new charts</s-text>
424→                <s-text color="subdued">
425→                  New charts are immediately set to Active instead of Draft.
426→                </s-text>
427→              </s-stack>
428→              <s-switch
429→                checked={autoPublish}
430→                onChange={(e: Event) => setAutoPublish((e.target as HTMLInputElement).checked)}
431→              />
432→            </s-stack>
433→
434→          </s-stack>
435→        </s-box>
436→      </s-section>
437→
438→      {/* ================================================================ */}
439→      {/* SECTION 3 — Data Management                                       */}
440→      {/* ================================================================ */}
441→      <s-section heading="Data Management">
442→        <s-stack direction="block" gap="base">
443→
444→          {/* Export */}
445→          <s-box padding="base" borderWidth="base" borderRadius="base">
446→            <s-stack direction="block" gap="small-200">
447→              <s-heading>Export size charts</s-heading>
448→              <s-text color="subdued">
449→                Download all {chartCount} chart{chartCount === 1 ? "" : "s"} as a JSON file. Includes all assignments and data. Use to back up or migrate to another store.
450→              </s-text>
451→              <s-button
452→                onClick={() => submitIntent("export-data")}
453→                loading={isLoading && fetcher.formData?.get("intent") === "export-data"}
454→                disabled={chartCount === 0}
455→              >
456→                Export all charts
457→              </s-button>
458→              {chartCount === 0 && (
459→                <s-text color="subdued">No charts to export.</s-text>
460→              )}
461→            </s-stack>
462→          </s-box>
463→
464→          {/* Import */}
465→          <s-box padding="base" borderWidth="base" borderRadius="base">
466→            <s-stack direction="block" gap="small-200">
467→              <s-heading>Import charts from JSON</s-heading>
468→              <s-text color="subdued">
469→                Paste your exported JSON backup below. Existing charts with the same name are skipped.
470→              </s-text>
471→              {!hasFeature(plan.id, "csvImport") && (
472→                <s-banner tone="warning" heading="Starter plan required">
473→                  <s-text color="subdued">
474→                    Import is available on the Starter plan ($4.99/mo) and above.
475→                  </s-text>
476→                </s-banner>
477→              )}
478→              <s-text-area
479→                label=""
480→                value={importJson}
481→                onChange={(e: Event) => setImportJson((e.target as HTMLTextAreaElement).value)}
482→                placeholder='{"charts": [...]}'
483→                rows={6}
484→                disabled={!hasFeature(plan.id, "csvImport")}
485→              />
486→              <s-button
487→                variant="primary"
488→                onClick={() => submitIntent("import-data", { importJson })}
489→                loading={isLoading && fetcher.formData?.get("intent") === "import-data"}
490→                disabled={!hasFeature(plan.id, "csvImport") || !importJson.trim()}
491→              >
492→                Import charts
493→              </s-button>
494→            </s-stack>
495→          </s-box>
496→
497→        </s-stack>
498→      </s-section>
499→
500→      {/* ================================================================ */}
501→      {/* SECTION 4 — Widget Settings Quick Access                          */}
502→      {/* ================================================================ */}
503→      <s-section heading="Widget Settings">
504→        <s-box padding="base" borderWidth="base" borderRadius="base">
505→          <s-stack direction="block" gap="small-200">
506→            <s-stack direction="inline" gap="small-200">
507→              <s-text>Widget status</s-text>
508→              <s-badge tone={hasWidgetConfig ? "success" : "neutral"}>
509→                {hasWidgetConfig ? "Configured" : "Using defaults"}
510→              </s-badge>
511→            </s-stack>
512→            {hasWidgetConfig && widgetDisplayMode && (
513→              <s-stack direction="inline" gap="small-200">
514→                <s-text color="subdued">Display mode</s-text>
515→                <s-badge tone="info">{widgetDisplayMode}</s-badge>
516→              </s-stack>
517→            )}
518→            <s-text color="subdued">
519→              {hasWidgetConfig
520→                ? "Widget is customized with your brand settings."
521→                : "Widget is using default appearance settings."}
522→            </s-text>
523→            <s-button-group>
524→              <s-button href="/app/widget" variant="primary">Open Widget Customizer</s-button>
525→              <s-button
526→                tone="critical"
527→                onClick={() => submitIntent("reset-widget")}
528→                loading={isLoading && fetcher.formData?.get("intent") === "reset-widget"}
529→                disabled={!hasWidgetConfig}
530→              >
531→                Reset to defaults
532→              </s-button>
533→            </s-button-group>
534→          </s-stack>
535→        </s-box>
536→      </s-section>
537→
538→      {/* ================================================================ */}
539→      {/* SECTION 5 — Danger Zone                                           */}
540→      {/* ================================================================ */}
541→      <s-section heading="Danger Zone">
542→        <s-banner tone="critical" heading="Irreversible actions">
543→          <s-text color="subdued">
544→            These actions cannot be undone. Proceed with caution.
545→          </s-text>
546→        </s-banner>
547→
548→        <s-stack direction="block" gap="base">
549→
550→          {/* Clear Analytics */}
551→          <s-box padding="base" borderWidth="base" borderRadius="base">
552→            <s-stack direction="block" gap="small-200">
553→              <s-text>Clear analytics data</s-text>
554→              <s-text color="subdued">
555→                Permanently delete all chart view events, recommendation events, and conversion data. This cannot be undone.
556→              </s-text>
557→              <s-button
558→                tone="critical"
559→                onClick={() => submitIntent("reset-analytics")}
560→                loading={isLoading && fetcher.formData?.get("intent") === "reset-analytics"}
561→              >
562→                Clear all analytics
563→              </s-button>
564→            </s-stack>
565→          </s-box>
566→
567→          {/* Delete All Charts */}
568→          <s-box padding="base" borderWidth="base" borderRadius="base">
569→            <s-stack direction="block" gap="small-200">
570→              <s-text>Delete all size charts</s-text>
571→              <s-text color="subdued">
572→                Permanently delete all {chartCount} size chart{chartCount === 1 ? "" : "s"} and their assignments. Type DELETE below to confirm.
573→              </s-text>
574→              <s-text-field
575→                label='Type "DELETE" to confirm'
576→                value={deleteConfirm}
577→                onChange={(e: Event) => setDeleteConfirm((e.target as HTMLInputElement).value)}
578→                placeholder="DELETE"
579→              />
580→              <s-button
581→                tone="critical"
582→                onClick={() => submitIntent("delete-all-charts", { confirmText: deleteConfirm })}
583→                loading={isLoading && fetcher.formData?.get("intent") === "delete-all-charts"}
584→                disabled={deleteConfirm !== "DELETE" || chartCount === 0}
585→              >
586→                Delete all charts
587→              </s-button>
588→            </s-stack>
589→          </s-box>
590→
591→        </s-stack>
592→      </s-section>
593→
594→      {/* ================================================================ */}
595→      {/* APP STATUS + SUPPORT (inline)                                      */}
596→      {/* ================================================================ */}
597→      <s-section heading="App Status">
598→        <s-box padding="base" borderWidth="base" borderRadius="base">
599→          <s-stack direction="inline" gap="base">
600→            <StatusRow
601→              label="Widget config"
602→              configured={hasWidgetConfig}
603→              configuredLabel="Configured"
604→              notConfiguredLabel="Using defaults"
605→            />
606→            <StatusRow
607→              label="AI Recommender"
608→              configured={recommenderEnabled}
609→              configuredLabel="Enabled"
610→              notConfiguredLabel={hasRecommenderConfig ? "Disabled" : "Not set up"}
611→            />
612→            <StatusRow
613→              label="Theme extension"
614→              configured={chartCount > 0}
615→              configuredLabel="Charts ready"
616→              notConfiguredLabel="No charts yet"
617→            />
618→            <s-stack direction="block" gap="small-100">
619→              <s-text color="subdued">Version</s-text>
620→              <s-stack direction="inline" gap="small-200">
621→                <s-text>1.0.0</s-text>
622→                <s-badge tone="success">Built for Shopify</s-badge>
623→              </s-stack>
624→            </s-stack>
625→            <s-stack direction="block" gap="small-100">
626→              <s-text color="subdued">Support</s-text>
627→              <s-stack direction="inline" gap="small-200">
628→                {isPriority ? <s-badge tone="success">Priority</s-badge> : <s-badge tone="neutral">Standard</s-badge>}
629→                <s-link href="mailto:support@sizechart.app">Email</s-link>
630→              </s-stack>
631→            </s-stack>
632→          </s-stack>
633→        </s-box>
634→      </s-section>
635→
636→    </s-page>
637→  );
638→}
