 13→interface BodyTypeConfig {
 14→  id: string;
 15→  label: string;
 16→  description: string;
 17→  enabled: boolean;
 18→}
 19→
 20→interface TestResult {
 21→  size: string;
 22→  confidence: number;
 23→  alternatives: string[];
 24→  bust: number;
 25→  waist: number;
 26→  hips: number;
 27→}
 28→
 29→const DEFAULT_BODY_TYPES: BodyTypeConfig[] = [
 30→  { id: "slim", label: "Slim", description: "Narrower proportions, prefers fitted styles", enabled: true },
 31→  { id: "regular", label: "Regular", description: "Standard proportions, true-to-size fits well", enabled: true },
 32→  { id: "athletic", label: "Athletic", description: "Broader chest/shoulders, narrower waist", enabled: true },
 33→  { id: "plus", label: "Plus", description: "Fuller proportions, relaxed fit preferences", enabled: true },
 34→  { id: "petite", label: "Petite", description: "Shorter stature, petite-specific proportions", enabled: false },
 35→];
 36→
 37→const DEFAULT_FIT_PREFERENCE = "true-to-size";
 38→const DEFAULT_ALGORITHM = "basic";
