 40→// ---------------------------------------------------------------------------
 41→// Loader
 42→// ---------------------------------------------------------------------------
 43→
 44→export const loader = async ({ request }: LoaderFunctionArgs) => {
 45→  const { session } = await authenticate.admin(request);
 46→  const shop = session.shop;
 47→
 48→  const [config, subscription, charts] = await Promise.all([
 49→    db.recommenderConfig.findUnique({ where: { shop } }),
 50→    db.subscription.findUnique({ where: { shop } }),
 51→    db.sizeChart.findMany({
 52→      where: { shop, status: "active" },
 53→      select: { id: true, name: true, category: true },
 54→      orderBy: { name: "asc" },
 55→    }),
 56→  ]);
 57→
 58→  const plan = getPlan(subscription?.planId ?? "free");
 59→  const canUseAi = hasFeature(plan.id, "aiRecommender");
 60→  const canUseAdvanced = hasFeature(plan.id, "advancedAi");
 61→
 62→  let bodyTypes = DEFAULT_BODY_TYPES;
 63→  if (config?.bodyTypes) {
 64→    try {
 65→      const saved = JSON.parse(config.bodyTypes) as Array<{ id: string; enabled: boolean }>;
 66→      bodyTypes = DEFAULT_BODY_TYPES.map((bt) => {
 67→        const match = saved.find((s) => s.id === bt.id);
 68→        return match ? { ...bt, enabled: match.enabled } : bt;
 69→      });
 70→    } catch {
 71→      bodyTypes = DEFAULT_BODY_TYPES;
 72→    }
 73→  }
 74→
 75→  let sizingRules: Record<string, string> = {};
 76→  if (config?.sizingRules) {
 77→    try {
 78→      sizingRules = JSON.parse(config.sizingRules) as Record<string, string>;
 79→    } catch {
 80→      sizingRules = {};
 81→    }
 82→  }
 83→
 84→  const fitPreference = (sizingRules.fitPreference as string) ?? DEFAULT_FIT_PREFERENCE;
 85→  const betweenSizes = (sizingRules.betweenSizes as string) ?? "larger";
 86→
 87→  return {
 88→    config: {
 89→      enabled: config?.enabled ?? false,
 90→      algorithm: config?.algorithm ?? DEFAULT_ALGORITHM,
 91→    },
 92→    bodyTypes,
 93→    fitPreference,
 94→    betweenSizes,
 95→    plan,
 96→    canUseAi,
 97→    canUseAdvanced,
 98→    charts,
 99→  };
100→};
