106→export const action = async ({ request }: ActionFunctionArgs) => {
107→  const { session } = await authenticate.admin(request);
108→  const shop = session.shop;
109→  const formData = await request.formData();
110→  const intent = formData.get("intent") as string;
111→
112→  try {
113→    switch (intent) {
114→      case "toggle": {
115→        const subscription = await db.subscription.findUnique({ where: { shop } });
116→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
117→          return { error: "AI recommender requires Growth plan or higher", intent };
118→        }
119→        const current = await db.recommenderConfig.findUnique({ where: { shop } });
120→        const newEnabled = !current?.enabled;
121→        await db.recommenderConfig.upsert({
122→          where: { shop },
123→          update: { enabled: newEnabled },
124→          create: { shop, enabled: newEnabled },
125→        });
126→        return {
127→          ok: true,
128→          intent,
129→          enabled: newEnabled,
130→          message: newEnabled ? "AI Recommender enabled" : "AI Recommender disabled",
131→        };
132→      }
133→
134→      case "update-settings": {
135→        const subscription = await db.subscription.findUnique({ where: { shop } });
136→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
137→          return { error: "AI recommender requires Growth plan or higher", intent };
138→        }
139→        const algorithm = (formData.get("algorithm") as string) || DEFAULT_ALGORITHM;
140→        await db.recommenderConfig.upsert({
141→          where: { shop },
142→          update: { algorithm },
143→          create: { shop, algorithm },
144→        });
145→        return { ok: true, intent, message: "Algorithm updated" };
146→      }
147→
148→      case "save-body-types": {
149→        const subscription = await db.subscription.findUnique({ where: { shop } });
150→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
151→          return { error: "AI recommender requires Growth plan or higher", intent };
152→        }
153→        const bodyTypesRaw = formData.get("bodyTypes") as string;
154→        if (!bodyTypesRaw) return { error: "No body types data", intent };
155→        await db.recommenderConfig.upsert({
156→          where: { shop },
157→          update: { bodyTypes: bodyTypesRaw },
158→          create: { shop, bodyTypes: bodyTypesRaw },
159→        });
160→        return { ok: true, intent, message: "Body types saved" };
161→      }
162→
163→      case "save-sizing-rules": {
164→        const subscription = await db.subscription.findUnique({ where: { shop } });
165→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
166→          return { error: "AI recommender requires Growth plan or higher", intent };
167→        }
168→        const fitPreference = (formData.get("fitPreference") as string) || DEFAULT_FIT_PREFERENCE;
169→        const betweenSizes = (formData.get("betweenSizes") as string) || "larger";
170→        const rules = JSON.stringify({ fitPreference, betweenSizes });
171→        await db.recommenderConfig.upsert({
172→          where: { shop },
173→          update: { sizingRules: rules },
174→          create: { shop, sizingRules: rules },
175→        });
176→        return { ok: true, intent, message: "Sizing rules saved" };
177→      }
178→
179→      case "test-recommendation": {
180→        const subscription = await db.subscription.findUnique({ where: { shop } });
181→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
182→          return { error: "AI recommender requires Growth plan or higher", intent };
183→        }
184→
185→        const heightCm = parseFloat(formData.get("height") as string);
186→        const weightKg = parseFloat(formData.get("weight") as string);
187→        const bodyType = (formData.get("bodyType") as string) || "regular";
188→        const fitPref = (formData.get("fitPreference") as string) || DEFAULT_FIT_PREFERENCE;
189→
190→        if (isNaN(heightCm) || isNaN(weightKg) || heightCm < 100 || heightCm > 250 || weightKg < 30 || weightKg > 250) {
191→          return { error: "Please enter valid height (100–250 cm) and weight (30–250 kg)", intent };
192→        }
193→
194→        // Statistical body proportion model (basic algorithm)
195→        const bmi = weightKg / ((heightCm / 100) ** 2);
196→
197→        const bodyTypeMultipliers: Record<string, { bust: number; waist: number; hips: number }> = {
198→          slim:    { bust: 0.52, waist: 0.43, hips: 0.54 },
199→          regular: { bust: 0.54, waist: 0.46, hips: 0.57 },
200→          athletic:{ bust: 0.56, waist: 0.44, hips: 0.56 },
201→          plus:    { bust: 0.59, waist: 0.52, hips: 0.62 },
202→          petite:  { bust: 0.52, waist: 0.44, hips: 0.55 },
203→        };
204→
205→        const fitBias: Record<string, number> = {
206→          "tight": -2,
207→          "true-to-size": 0,
208→          "relaxed": 2,
209→          "oversized": 4,
210→        };
211→
212→        const mult = bodyTypeMultipliers[bodyType] ?? bodyTypeMultipliers.regular;
213→        const bias = fitBias[fitPref] ?? 0;
214→
215→        const bust = Math.round(heightCm * mult.bust + bias);
216→        const waist = Math.round(heightCm * mult.waist + (bmi - 22) * 0.5 + bias);
217→        const hips = Math.round(heightCm * mult.hips + bias);
218→
219→        // Size chart lookup (bust-based for tops/general)
220→        const sizes = [
221→          { label: "XS", bustMin: 76, bustMax: 83 },
222→          { label: "S",  bustMin: 84, bustMax: 91 },
223→          { label: "M",  bustMin: 92, bustMax: 99 },
224→          { label: "L",  bustMin: 100, bustMax: 107 },
225→          { label: "XL", bustMin: 108, bustMax: 115 },
226→          { label: "2XL",bustMin: 116, bustMax: 123 },
227→          { label: "3XL",bustMin: 124, bustMax: 131 },
228→        ];
229→
230→        const matched = sizes.find((s) => bust >= s.bustMin && bust <= s.bustMax);
231→        const matchedIdx = matched ? sizes.indexOf(matched) : 2;
232→        const size = matched?.label ?? "M";
233→        const confidence = matched
234→          ? Math.round(90 - Math.abs(bust - (matched.bustMin + matched.bustMax) / 2) * 0.8)
235→          : 65;
236→
237→        const alternatives: string[] = [];
238→        if (matchedIdx > 0) alternatives.push(sizes[matchedIdx - 1].label);
239→        if (matchedIdx < sizes.length - 1) alternatives.push(sizes[matchedIdx + 1].label);
240→
241→        return {
242→          ok: true,
243→          intent,
244→          testResult: { size, confidence, alternatives, bust, waist, hips } as TestResult,
245→          message: `Recommended size: ${size}`,
246→        };
247→      }
248→
249→      default:
250→        return { error: "Unknown action", intent };
251→    }
252→  } catch (error) {
253→    const message = error instanceof Error ? error.message : "An unexpected error occurred";
254→    return { error: message, intent };
255→  }
256→};
