import { useEffect, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, useNavigate } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";
import {
  Page,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  ButtonGroup,
  Banner,
  Divider,
  InlineGrid,
  TextField,
  Select,
  Checkbox,
} from "@shopify/polaris";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface GeneralSettings {
  unitSystem: string;
  defaultCategory: string;
  autoPublish: boolean;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [
    chartCount,
    assignmentCount,
    widgetConfig,
    recommenderConfig,
    subscription,
  ] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.chartAssignment.count({ where: { shop } }),
    db.widgetConfig.findUnique({ where: { shop } }),
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  return {
    shop,
    chartCount,
    assignmentCount,
    hasWidgetConfig: widgetConfig !== null,
    widgetDisplayMode: widgetConfig?.displayMode ?? null,
    hasRecommenderConfig: recommenderConfig !== null,
    recommenderEnabled: recommenderConfig?.enabled ?? false,
    plan,
    isPriority: hasFeature(plan.id, "prioritySupport"),
    isFreePlan: plan.id === "free",
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "export-data": {
        const charts = await db.sizeChart.findMany({
          where: { shop },
          include: { assignments: true },
        });
        const payload = {
          exportedAt: new Date().toISOString(),
          shop,
          charts: charts.map((c) => ({
            id: c.id,
            name: c.name,
            type: c.type,
            category: c.category,
            data: c.data,
            isDefault: c.isDefault,
            status: c.status,
            createdAt: c.createdAt.toISOString(),
            assignments: c.assignments.map((a) => ({
              assignmentType: a.assignmentType,
              assignmentValue: a.assignmentValue,
            })),
          })),
        };
        return {
          ok: true,
          intent: "export-data",
          message: `${charts.length} chart${charts.length === 1 ? "" : "s"} exported`,
          exportData: JSON.stringify(payload, null, 2),
        };
      }

      case "import-data": {
        const jsonRaw = formData.get("importJson") as string;
        if (!jsonRaw?.trim()) {
          return { error: "No JSON data provided", intent: "import-data" };
        }
        let parsed: { charts?: Array<{
          name: string;
          type?: string;
          category?: string;
          data?: string;
          isDefault?: boolean;
          status?: string;
          assignments?: Array<{ assignmentType: string; assignmentValue: string }>;
        }> };
        try {
          parsed = JSON.parse(jsonRaw) as typeof parsed;
        } catch {
          return { error: "Invalid JSON format", intent: "import-data" };
        }
        if (!Array.isArray(parsed.charts)) {
          return { error: "JSON must contain a 'charts' array", intent: "import-data" };
        }
        let imported = 0;
        for (const chart of parsed.charts) {
          if (!chart.name) continue;
          const existing = await db.sizeChart.findFirst({
            where: { shop, name: chart.name },
          });
          if (existing) continue;
          await db.sizeChart.create({
            data: {
              shop,
              name: chart.name,
              type: chart.type ?? "table",
              category: chart.category ?? "general",
              data: chart.data ?? "{}",
              isDefault: chart.isDefault ?? false,
              status: chart.status ?? "draft",
              assignments: chart.assignments
                ? {
                    create: chart.assignments.map((a) => ({
                      shop,
                      assignmentType: a.assignmentType,
                      assignmentValue: a.assignmentValue,
                    })),
                  }
                : undefined,
            },
          });
          imported++;
        }
        return {
          ok: true,
          intent: "import-data",
          message: `${imported} chart${imported === 1 ? "" : "s"} imported successfully`,
        };
      }

      case "reset-widget": {
        await db.widgetConfig.deleteMany({ where: { shop } });
        return { ok: true, intent: "reset-widget", message: "Widget settings reset to defaults" };
      }

      case "reset-analytics": {
        const deleted = await db.analyticsEvent.deleteMany({ where: { shop } });
        return {
          ok: true,
          intent: "reset-analytics",
          message: `${deleted.count} analytics event${deleted.count === 1 ? "" : "s"} cleared`,
        };
      }

      case "delete-all-charts": {
        const confirm = formData.get("confirmText") as string;
        if (confirm !== "DELETE") {
          return { error: "Type DELETE to confirm", intent: "delete-all-charts" };
        }
        const deleted = await db.sizeChart.deleteMany({ where: { shop } });
        return {
          ok: true,
          intent: "delete-all-charts",
          message: `${deleted.count} chart${deleted.count === 1 ? "" : "s"} deleted`,
        };
      }

      default:
        return { error: "Unknown action", intent };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred";
    return { error: message, intent };
  }
};

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

function StatCard({
  label,
  value,
  sub,
}: {
  label: string;
  value: string | number;
  sub?: string;
}) {
  return (
    <Card>
      <BlockStack gap="200">
        <Text as="h2" variant="headingMd" fontWeight="bold">{String(value)}</Text>
        <Text as="p" variant="bodyMd" tone="subdued">{label}</Text>
        {sub && <Text as="p" variant="bodyMd" tone="subdued">{sub}</Text>}
      </BlockStack>
    </Card>
  );
}

function StatusRow({
  label,
  configured,
  configuredLabel,
  notConfiguredLabel,
}: {
  label: string;
  configured: boolean;
  configuredLabel: string;
  notConfiguredLabel: string;
}) {
  return (
    <InlineStack gap="400" blockAlign="center">
      <Text as="p" variant="bodyMd">{label}</Text>
      <Badge tone={configured ? "success" : "enabled"}>
        {configured ? configuredLabel : notConfiguredLabel}
      </Badge>
    </InlineStack>
  );
}

