        <BlockStack gap="200">
          <InlineStack gap="200" blockAlign="center">
            <Text as="p" variant="bodyMd">{label}</Text>
            {selected && <Badge tone="info">Active</Badge>}
          </InlineStack>
          <Text as="p" variant="bodyMd" tone="subdued">{description}</Text>
          <Badge tone={badgeTone as "success" | "enabled" | "warning" | "critical" | "info"}>{badge}</Badge>
        </BlockStack>
      </Card>
    </div>
  );
}

function FitCard({
  id,
  label,
  description,
  selected,
  onSelect,
}: {
  id: string;
  label: string;
  description: string;
  selected: boolean;
  onSelect: (v: string) => void;
}) {
  return (
    <div
      onClick={() => onSelect(id)}
      style={{
        cursor: "pointer",
        borderRadius: "12px",
        outline: selected ? "2px solid #005bd3" : "none",
        flex: "1 1 0",
        minWidth: "120px",
      }}
    >
      <Card>
        <BlockStack gap="200">
          <InlineStack gap="200" blockAlign="center">
            <Text as="p" variant="bodyMd">{label}</Text>
            {selected && <Badge tone="info">Selected</Badge>}
          </InlineStack>
          <Text as="p" variant="bodyMd" tone="subdued">{description}</Text>
        </BlockStack>
      </Card>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

export default function Recommender() {
  const {
    config,
    bodyTypes: initialBodyTypes,
    fitPreference: initialFitPreference,
    betweenSizes: initialBetweenSizes,
    plan,
    canUseAi,
    canUseAdvanced,
    charts,
  } = useLoaderData<typeof loader>();

  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();
  const isLoading = fetcher.state !== "idle";

  // Local state that mirrors the DB-loaded values
  const [enabled, setEnabled] = useState<boolean>(config.enabled);
  const [algorithm, setAlgorithm] = useState<string>(config.algorithm);
  const [bodyTypes, setBodyTypes] = useState<BodyTypeConfig[]>(initialBodyTypes);
  const [fitPreference, setFitPreference] = useState<string>(initialFitPreference);
  const [betweenSizes, setBetweenSizes] = useState<string>(initialBetweenSizes);

  // Test recommendation inputs
  const [testChartId, setTestChartId] = useState<string>(charts[0]?.id ?? "");
  const [testHeight, setTestHeight] = useState<string>("170");
  const [testWeight, setTestWeight] = useState<string>("65");
  const [testGender, setTestGender] = useState<string>("female");
  const [testBodyType, setTestBodyType] = useState<string>("regular");
  const [testResult, setTestResult] = useState<TestResult | null>(null);

  useEffect(() => {
    if (!fetcher.data) return;

    if ("ok" in fetcher.data) {
      shopify.toast.show(fetcher.data.message ?? "Saved");

      if (fetcher.data.intent === "toggle" && "enabled" in fetcher.data) {
        setEnabled(fetcher.data.enabled as boolean);
      }

      if (fetcher.data.intent === "test-recommendation" && "testResult" in fetcher.data) {
        setTestResult(fetcher.data.testResult as TestResult);
      }
    } else if ("error" in fetcher.data) {
      shopify.toast.show(fetcher.data.error ?? "An error occurred", { isError: true });
    }
  }, [fetcher.data, shopify]);

  const submitToggle = () => {
    const fd = new FormData();
    fd.set("intent", "toggle");
    fetcher.submit(fd, { method: "post" });
  };

  const submitAlgorithm = (algo: string) => {
    setAlgorithm(algo);
    const fd = new FormData();
    fd.set("intent", "update-settings");
    fd.set("algorithm", algo);
    fetcher.submit(fd, { method: "post" });
  };

  const toggleBodyType = (id: string, checked: boolean) => {
    const updated = bodyTypes.map((bt) => bt.id === id ? { ...bt, enabled: checked } : bt);
    setBodyTypes(updated);
    const fd = new FormData();
    fd.set("intent", "save-body-types");
    fd.set("bodyTypes", JSON.stringify(updated.map((bt) => ({ id: bt.id, enabled: bt.enabled }))));
    fetcher.submit(fd, { method: "post" });
  };

  const submitSizingRules = () => {
    const fd = new FormData();
    fd.set("intent", "save-sizing-rules");
    fd.set("fitPreference", fitPreference);
    fd.set("betweenSizes", betweenSizes);
    fetcher.submit(fd, { method: "post" });
  };

  const submitTestRecommendation = () => {
    const fd = new FormData();
    fd.set("intent", "test-recommendation");
    fd.set("chartId", testChartId);
    fd.set("height", testHeight);
    fd.set("weight", testWeight);
    fd.set("gender", testGender);
    fd.set("bodyType", testBodyType);
    fd.set("fitPreference", fitPreference);
    fetcher.submit(fd, { method: "post" });
  };

  const FIT_OPTIONS = [
    { id: "tight", label: "Tight", description: "Fitted, closer to body — recommend smaller" },
    { id: "true-to-size", label: "True to Size", description: "Standard fit — no adjustment" },
    { id: "relaxed", label: "Relaxed", description: "Slightly loose — recommend larger" },
    { id: "oversized", label: "Oversized", description: "Very loose, fashion-forward — recommend up" },
  ];

  const betweenSizesOptions = [
    { label: "Recommend smaller size", value: "smaller" },
    { label: "Recommend larger size", value: "larger" },
  ];

  const genderOptions = [
    { label: "Female", value: "female" },
    { label: "Male", value: "male" },
    { label: "Unisex", value: "unisex" },
  ];

  const chartOptions = charts.map((c) => ({
    label: `${c.name} (${c.category})`,
    value: c.id,
  }));

  const enabledBodyTypeOptions = bodyTypes
    .filter((bt) => bt.enabled)
    .map((bt) => ({ label: bt.label, value: bt.id }));

  // -----------------------------------------------------------------------
  // UPGRADE PROMPT — plan doesn't include AI
  // -----------------------------------------------------------------------
  if (!canUseAi) {
    return (
      <Page
        title="AI Size Recommender"
        backAction={{ onAction: () => navigate("/app") }}
      >
        <BlockStack gap="600">
          <Card>
            <BlockStack gap="400">
              <Text as="h2" variant="headingMd" fontWeight="bold">Unlock AI Size Recommendations</Text>
              <Text as="p" variant="bodyMd" tone="subdued">
                Help customers find their perfect fit using height, weight, and body type. Reduce size-related returns by up to 40%.
              </Text>

              <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
                <Card>
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd">Personalized sizing</Text>
                    <Text as="p" variant="bodyMd" tone="subdued">Customers enter their measurements and get an instant size recommendation.</Text>
                  </BlockStack>
                </Card>
                <Card>
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd">No API costs</Text>
                    <Text as="p" variant="bodyMd" tone="subdued">All computation runs server-side. No per-request fees, ever.</Text>
                  </BlockStack>
                </Card>
                <Card>
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd">Confidence scores</Text>
                    <Text as="p" variant="bodyMd" tone="subdued">Each recommendation shows a confidence percentage and alternatives.</Text>
                  </BlockStack>
                </Card>
              </InlineGrid>

              <Banner tone="info" title="Available on Growth plan — $9.99/mo">
                <BlockStack gap="200">
                  <List type="bullet">
                    <List.Item>Basic AI recommender included</List.Item>
                    <List.Item>Analytics dashboard</List.Item>
                    <List.Item>Unlimited charts + Translate &amp; Adapt</List.Item>
                  </List>
                  <Button variant="primary" url="/app/pricing">
                    Upgrade to Growth — $9.99/mo
                  </Button>
                </BlockStack>
              </Banner>
            </BlockStack>
          </Card>
        </BlockStack>
      </Page>
    );
  }

  // -----------------------------------------------------------------------
  // FULL PAGE — plan allows AI
  // -----------------------------------------------------------------------
  return (
    <Page
      title="AI Size Recommender"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={
        <Button
          variant={enabled ? "secondary" : "primary"}
          onClick={submitToggle}
          loading={isLoading && fetcher.formData?.get("intent") === "toggle"}
        >
          {enabled ? "Disable Recommender" : "Enable Recommender"}
        </Button>
      }
    >
      <BlockStack gap="600">

        {/* ================================================================ */}
        {/* SECTION 1 — Recommender Status                                    */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Recommender Status</Text>

            <InlineStack gap="400" blockAlign="start">
              <BlockStack gap="200">
                <InlineStack gap="200" blockAlign="center">
                  <Text as="p" variant="bodyMd">Status</Text>
                  <Badge tone={enabled ? "success" : "enabled"}>
                    {enabled ? "Active" : "Disabled"}
                  </Badge>
                </InlineStack>
                <Text as="p" variant="bodyMd" tone="subdued">
                  {enabled
                    ? 'Customers see a "Find My Size" button on product pages. The AI returns a recommended size with confidence score and alternatives.'
                    : 'Enable to show the "Find My Size" button on product pages. Customers enter height, weight, and body type to get personalized recommendations.'}
                </Text>
              </BlockStack>
              <Checkbox
                label="Enable AI Recommender"
                labelHidden
                checked={enabled}
                onChange={(checked) => {
                  if (checked !== enabled) submitToggle();
                }}
              />
            </InlineStack>

            {enabled && (
              <Banner tone="success" title="Recommender is live on your storefront">
                <Text as="p" variant="bodyMd" tone="subdued">
                  Customers can now get personalized size recommendations. Check the analytics dashboard to track recommendation events.
                </Text>
              </Banner>
            )}
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 2 — How It Works                                          */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">How It Works</Text>
            <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
              <Card>
                <BlockStack gap="200">
                  <InlineStack gap="200" blockAlign="center">
                    <Badge tone="info">Step 1</Badge>
                    <Text as="p" variant="bodyMd">Customer enters info</Text>
                  </InlineStack>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Height, weight, body type, and gender are submitted via the "Find My Size" form in the storefront widget.
                  </Text>
                </BlockStack>
              </Card>

              <Card>
                <BlockStack gap="200">
                  <InlineStack gap="200" blockAlign="center">
                    <Badge tone="info">Step 2</Badge>
                    <Text as="p" variant="bodyMd">AI estimates measurements</Text>
                  </InlineStack>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Our algorithm uses statistical body proportion models to estimate bust, waist, and hip measurements from the customer's inputs.
                  </Text>
                </BlockStack>
              </Card>

              <Card>
                <BlockStack gap="200">
                  <InlineStack gap="200" blockAlign="center">
                    <Badge tone="info">Step 3</Badge>
                    <Text as="p" variant="bodyMd">Best size shown</Text>
                  </InlineStack>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    The closest size from your chart is returned with a confidence percentage and one or two alternative sizes.
                  </Text>
                </BlockStack>
              </Card>
            </InlineGrid>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 3 — Algorithm Selection                                   */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Algorithm</Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              Choose the recommendation algorithm. Changes are saved immediately.
            </Text>
            <div style={{ display: "flex", gap: "16px", flexWrap: "wrap" }}>
              <AlgorithmCard
                id="basic"
                label="Basic (Statistical)"
                description="Statistical body proportion model built from thousands of measurements. Fast and accurate with no training data required."
                badge="Included in Growth"
                badgeTone="success"
                selected={algorithm === "basic"}
                disabled={false}
                onSelect={submitAlgorithm}
              />
              <AlgorithmCard
                id="advanced"
                label="Advanced ML"
                description="Machine learning model that improves over time using your store's return and exchange data for higher accuracy."
                badge={canUseAdvanced ? "Included in Pro" : "Requires Pro — $19.99/mo"}
                badgeTone={canUseAdvanced ? "success" : "warning"}
                selected={algorithm === "advanced"}
                disabled={!canUseAdvanced}
                onSelect={submitAlgorithm}
              />
            </div>
            {!canUseAdvanced && (
              <InlineStack gap="200" blockAlign="center">
                <Text as="p" variant="bodyMd" tone="subdued">
                  Advanced ML is available on the Pro plan.
                </Text>
                <Button variant="plain" url="/app/pricing">Upgrade to Pro — $19.99/mo</Button>
              </InlineStack>
            )}
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 4 — Body Type Configuration                               */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Body Types</Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              Choose which body types customers can select in the recommendation form. Changes are saved immediately.
            </Text>
            <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="400">
              {bodyTypes.map((bt) => (
                <div
                  key={bt.id}
                  style={{
                    borderRadius: "12px",
                    outline: bt.enabled ? "2px solid #005bd3" : "none",
                  }}
                >
                  <Card>
                    <BlockStack gap="200">
                      <InlineStack gap="400" blockAlign="start">
                        <BlockStack gap="100">
                          <Text as="p" variant="bodyMd">{bt.label}</Text>
                          <Text as="p" variant="bodyMd" tone="subdued">{bt.description}</Text>
                        </BlockStack>
                        <Checkbox
                          label={`Enable ${bt.label}`}
                          labelHidden
                          checked={bt.enabled}
                          onChange={(checked) => toggleBodyType(bt.id, checked)}
                        />
                      </InlineStack>
                      {bt.enabled && <Badge tone="success">Shown to customers</Badge>}
                    </BlockStack>
                  </Card>
                </div>
              ))}
            </InlineGrid>
            {bodyTypes.filter((bt) => bt.enabled).length === 0 && (
              <Banner tone="warning" title="No body types enabled">
                <Text as="p" variant="bodyMd" tone="subdued">Enable at least one body type so customers can use the recommender.</Text>
              </Banner>
            )}
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 5 — Fit Preference                                         */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Fit Preference Bias</Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              Set the default fit bias for your store. This shifts recommendations toward larger or smaller sizes depending on your typical customer preference.
            </Text>
            <div style={{ display: "flex", gap: "16px", flexWrap: "wrap" }}>
              {FIT_OPTIONS.map((opt) => (
                <FitCard
                  key={opt.id}
                  id={opt.id}
                  label={opt.label}
                  description={opt.description}
                  selected={fitPreference === opt.id}
                  onSelect={(v) => setFitPreference(v)}
                />
              ))}
            </div>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 6 — Custom Sizing Rules                                   */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Sizing Rules</Text>

            <BlockStack gap="200">
              <Text as="p" variant="bodyMd">When customer is between two sizes</Text>
              <Text as="p" variant="bodyMd" tone="subdued">
                If measurements fall exactly between two sizes, recommend the smaller or the larger one.
              </Text>
              <Select
                label="Between sizes preference"
                labelHidden
                options={betweenSizesOptions}
                value={betweenSizes}
                onChange={(value) => setBetweenSizes(value)}
              />
            </BlockStack>

            <InlineStack gap="200">
              <Button
                variant="primary"
                onClick={submitSizingRules}
                loading={isLoading && fetcher.formData?.get("intent") === "save-sizing-rules"}
              >
                Save sizing rules
              </Button>
            </InlineStack>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 7 — Test Recommendation                                   */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Test Recommendation</Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              Enter sample customer inputs to preview what your recommender would suggest. This uses the saved algorithm and sizing rules.
            </Text>

            <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
              <BlockStack gap="200">
                <Text as="p" variant="bodyMd">Chart to test against</Text>
                {charts.length === 0 ? (
                  <InlineStack gap="200" blockAlign="center">
                    <Text as="p" variant="bodyMd" tone="subdued">No active charts.</Text>
                    <Button variant="plain" url="/app/size-charts">Create a chart</Button>
                    <Text as="p" variant="bodyMd" tone="subdued">first.</Text>
                  </InlineStack>
                ) : (
                  <Select
                    label="Chart"
                    labelHidden
                    options={chartOptions}
                    value={testChartId}
                    onChange={(value) => setTestChartId(value)}
                  />
                )}
              </BlockStack>

              <BlockStack gap="200">
                <Text as="p" variant="bodyMd">Gender</Text>
                <Select
                  label="Gender"
                  labelHidden
                  options={genderOptions}
                  value={testGender}
                  onChange={(value) => setTestGender(value)}
                />
              </BlockStack>

              <BlockStack gap="200">
                <Text as="p" variant="bodyMd">Body type</Text>
                <Select
                  label="Body type"
                  labelHidden
                  options={enabledBodyTypeOptions}
                  value={testBodyType}
                  onChange={(value) => setTestBodyType(value)}
                />
              </BlockStack>
            </InlineGrid>

            <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
              <TextField
                label="Height (cm)"
                type="number"
                value={testHeight}
                onChange={(value) => setTestHeight(value)}
                autoComplete="off"
                min={100}
                max={250}
              />
              <TextField
                label="Weight (kg)"
                type="number"
                value={testWeight}
                onChange={(value) => setTestWeight(value)}
                autoComplete="off"
                min={30}
                max={250}
              />
            </InlineGrid>

            <InlineStack gap="200">
              <Button
                variant="primary"
                onClick={submitTestRecommendation}
                loading={isLoading && fetcher.formData?.get("intent") === "test-recommendation"}
                disabled={charts.length === 0}
              >
                Test recommendation
              </Button>
            </InlineStack>

            {testResult && (
              <Card>
                <BlockStack gap="200">
                  <InlineStack gap="200" blockAlign="center">
                    <Text as="h2" variant="headingMd" fontWeight="bold">{testResult.size}</Text>
                    <Badge tone={testResult.confidence >= 85 ? "success" : testResult.confidence >= 70 ? "info" : "warning"}>
                      {testResult.confidence}% confidence
                    </Badge>
                  </InlineStack>
                  {testResult.alternatives.length > 0 && (
                    <InlineStack gap="200" blockAlign="center">
                      <Text as="p" variant="bodyMd" tone="subdued">Alternatives:</Text>
                      {testResult.alternatives.map((alt) => (
                        <Badge key={alt} tone="enabled">{alt}</Badge>
                      ))}
                    </InlineStack>
                  )}
                  <Divider />
                  <Text as="p" variant="bodyMd" tone="subdued">Estimated measurements</Text>
                  <InlineGrid columns={{ xs: 3 }} gap="400">
                    <BlockStack gap="100">
                      <Text as="p" variant="bodyMd" tone="subdued">Bust</Text>
                      <Text as="p" variant="bodyMd">{testResult.bust} cm</Text>
                    </BlockStack>
                    <BlockStack gap="100">
                      <Text as="p" variant="bodyMd" tone="subdued">Waist</Text>
                      <Text as="p" variant="bodyMd">{testResult.waist} cm</Text>
                    </BlockStack>
                    <BlockStack gap="100">
                      <Text as="p" variant="bodyMd" tone="subdued">Hips</Text>
                      <Text as="p" variant="bodyMd">{testResult.hips} cm</Text>
                    </BlockStack>
                  </InlineGrid>
                </BlockStack>
              </Card>
            )}
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* PERFORMANCE + PLAN (inline bar)                                    */}
        {/* ================================================================ */}
        <Card>
          <InlineStack gap="400" blockAlign="center" wrap>
            <InlineStack gap="200" blockAlign="center">
              <Badge tone="success">{plan.name}</Badge>
              <Text as="p" variant="bodyMd" tone="subdued">${plan.price}/mo</Text>
            </InlineStack>
            <InlineStack gap="200" blockAlign="center">
              <Text as="p" variant="bodyMd" tone="subdued">Basic: ~5ms</Text>
              <Text as="p" variant="bodyMd" tone="subdued">Advanced: ~50ms</Text>
              <Text as="p" variant="bodyMd" tone="subdued">$0/recommendation</Text>
            </InlineStack>
            <Badge tone="success">GDPR compliant</Badge>
            {!canUseAdvanced && (
              <Button url="/app/pricing">Upgrade for Advanced ML</Button>
            )}
          </InlineStack>
        </Card>

      </BlockStack>
    </Page>
  );
}
